/** 이 시각이 로또 회차인가 */
export function 로또회차인가(시각, 목록 = 로또회차) {
  const h = String(시각 ?? "").padStart(2, "0");
  return 목록.some(([시]) => 시 === h);
}

/**
 * **지금이 로또를 거둘 때인가** — 토요일 21시부터 자정까지.
 * ⚠ 회차가 21:30 에 돌고 글을 쓰는 데 시간이 걸린다. 22·23시에 와도 거둔다.
 * ⛔ 토요일이 아니면 언제라도 아니다. 다른 날 밤에 열어 둘 까닭이 없다.
 */
export function 로또거둘때인가(이제 = new Date()) {
  if (!(이제 instanceof Date) || Number.isNaN(이제.getTime())) return false;
  if (이제.getDay() !== 6) return false;          /* 6 = 토요일 */
  const h = 이제.getHours();
  return h >= 21 && h <= 23;
}

/** 이 시각이 날씨 회차인가 */
export function 날씨회차인가(시각, 목록 = 날씨회차) {
  const h = String(시각 ?? "").padStart(2, "0");
  return 목록.some(([시]) => 시 === h);
}

