export function 오늘거둘회차(오늘날짜, 전체 = 온회차) {
  const 짚은것 = 줄이는날[String(오늘날짜)];
  if (!짚은것) return 전체;
  return 전체.filter(([시]) => 짚은것.includes(시));
}

const 오늘KST = (() => {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
})();

